"use client";

import * as Sentry from "@sentry/nextjs";
import { useEffect, useState } from "react";
import { useSearchParams, useRouter } from "next/navigation";
import Breadcrumb from "@/components/header/breadcrumb";
import Pagination from "../pagination/pagination";
import { getBlogPosts } from "@/services/blog";
import PostItem from "@/components/blog/PostItem";
import "./blogList.css";
import AttractionsListSkeleton from "@/components/attractions-page/list-skeleton";

interface BlogListProps {
  initialData: {
    posts: any[];
    totalPosts: number;
    categories: any[];
  };
}

export default function BlogList({ initialData }: BlogListProps) {
  const searchParams = useSearchParams();
  const router = useRouter();
  const [data, setData] = useState(initialData.posts);
  const [selectedCategory, setSelectedCategory] = useState<string>(searchParams.get('category') || "");
  const [sortBy, setSortBy] = useState<string>(searchParams.get('sort') || "newest");
  const [searchInput, setSearchInput] = useState("");
  const [searchTerm, setSearchTerm] = useState("");
  const [currentPage, setCurrentPage] = useState(1);
  const [totalPosts, setTotalPosts] = useState(initialData.totalPosts);
  const [loading, setLoading] = useState(false);
  const [categories] = useState(initialData.categories);
  const [hasInitialized, setHasInitialized] = useState(false);

  const pagination = async ({ page }: { page: number }) => {
    scroll(0, 0);
    setCurrentPage(page);
  };

  const onSearchChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    setSearchInput(e.target.value);
  };

  const handleSearchSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setCurrentPage(1);
    setSearchTerm(searchInput);
    setSelectedCategory("");
  };

  const onCategoryClick = async (category: string) => {
    setSelectedCategory(category);
    setCurrentPage(1);
    setSearchTerm("");
    setSearchInput("");
    
    // Update URL
    const params = new URLSearchParams(searchParams.toString());
    if (category) {
      params.set('category', category);
    } else {
      params.delete('category');
    }
    router.push(`/blog?${params.toString()}`);
  };

  useEffect(() => {
    async function loadPosts() {
      try {
        setLoading(true);
        const res = await getBlogPosts({ 
          page: currentPage, 
          search: searchTerm, 
          category: selectedCategory, 
          author_id: "",
          tag: "",
          sort: sortBy
        });
        setData(res.data);
        setTotalPosts(res.meta.total);
      } catch (err) {
        Sentry.captureException(err);
      } finally {
        setLoading(false);
      }
    }
    
    // Load posts if there's a category/sort from URL or after initialization
    if (hasInitialized || searchParams.get('category') || searchParams.get('sort')) {
      loadPosts();
    } else {
      setHasInitialized(true);
    }
  }, [selectedCategory, searchTerm, currentPage, sortBy]);

  if (loading)
    return (
      <div className="tw-max-w-[1320px] tw-mx-auto tw-px-4 tw-py-5">
        <AttractionsListSkeleton />
      </div>
    );

  const catBtnCls =
    "tw-w-full tw-flex tw-justify-between tw-text-left tw-bg-transparent tw-border-0 tw-cursor-pointer tw-text-[14px] tw-px-2 tw-py-1.5 tw-rounded-md hover:tw-bg-[#f5f4f7] tw-transition-colors";

  return (
    <main>
      <div className="tw-max-w-[1320px] tw-mx-auto tw-px-4 tw-my-6 tw-font-display">
        <Breadcrumb items={[{ pageTitle: "Blog", pageUrl: "/blog" }]} />
        <div className="tw-mb-8">
          <h1 className="tw-text-[clamp(28px,4vw,40px)] tw-font-extrabold tw-tracking-tight tw-text-[#14101c] tw-m-0">
            The TravelShop Journal
          </h1>
          <p className="tw-mt-2 tw-mb-0 tw-text-[15px] tw-text-[#5d556c] tw-max-w-[60ch]">
            Travel stories, destination guides and expert tips from explorers
            around the world.
          </p>
        </div>

        <div className="tw-grid tw-grid-cols-1 lg:tw-grid-cols-12 tw-gap-8">
          <div className="lg:tw-col-span-9">
            {data.length === 0 && searchTerm && (
              <div className="tw-text-center tw-mt-12 tw-text-[#5d556c]">
                No post found with the search criteria
              </div>
            )}

            {data.length === 0 && !searchTerm && (
              <div className="tw-text-center tw-mt-12 tw-text-[#5d556c]">
                No post found.
              </div>
            )}

            <div className="tw-grid tw-grid-cols-1 sm:tw-grid-cols-2 lg:tw-grid-cols-3 tw-gap-4 tw-mt-4">
              {data.map((item: any, index: number) => (
                <PostItem key={index} post={item} mainList={false} />
              ))}
            </div>

            <div className="tw-mt-6">
              <div className="tw-text-[#5d556c] tw-text-center tw-text-[13px] tw-mb-2">
                Showing {data.length} of {totalPosts} {totalPosts > 1 ? "posts" : "post"}
              </div>
              <Pagination
                currentPage={currentPage}
                totalCount={totalPosts}
                pageSize="12"
                onPageChange={(page: number) => pagination({ page })}
              />
            </div>
          </div>

          <div className="lg:tw-col-span-3">
            <div className="tw-rounded-2xl tw-border tw-border-solid tw-border-[#eceaf1] tw-bg-white tw-p-4 tw-mb-4">
              <h6 className="tw-text-[15px] tw-font-semibold tw-text-[#14101c] tw-mb-3">
                Search Posts
              </h6>
              <form onSubmit={handleSearchSubmit}>
                <div className="tw-flex">
                  <input
                    type="text"
                    className="tw-flex-1 tw-min-w-0 tw-rounded-l-lg tw-border tw-border-solid tw-border-[#d6d2de] tw-border-r-0 tw-px-3 tw-py-2 tw-text-[14px] tw-outline-none focus:tw-border-[#854ec9] tw-transition-colors"
                    placeholder="Search by title..."
                    value={searchInput}
                    onChange={onSearchChange}
                  />
                  <button
                    type="submit"
                    className="tw-rounded-r-lg tw-bg-[#854ec9] hover:tw-bg-[#6a3da4] tw-text-white tw-text-[14px] tw-font-semibold tw-px-3 tw-py-2 tw-border-0 tw-cursor-pointer tw-transition-colors"
                  >
                    Search
                  </button>
                </div>
              </form>
            </div>

            <div className="tw-rounded-2xl tw-border tw-border-solid tw-border-[#eceaf1] tw-bg-white tw-p-4">
              <h4 className="tw-text-[16px] tw-font-semibold tw-text-[#14101c] tw-mb-3">
                Categories
              </h4>
              <ul className="tw-list-none tw-p-0 tw-m-0">
                <li className="tw-mb-1 tw-border-0 tw-border-b tw-border-solid tw-border-[#eceaf1] tw-pb-1">
                  <button
                    className={`${catBtnCls} ${
                      selectedCategory === "" ? "tw-text-[#854ec9] tw-font-semibold" : "tw-text-[#14101c]"
                    }`}
                    onClick={() => onCategoryClick("")}
                  >
                    <span>All categories</span>
                    <span>({categories.reduce((sum, cat) => sum + (cat.post_count || 0), 0)})</span>
                  </button>
                </li>
                {categories.map((cat: any) => (
                  <li
                    key={cat.slug}
                    className="tw-mb-1 tw-border-0 tw-border-b tw-border-solid tw-border-[#eceaf1] tw-pb-1"
                  >
                    <button
                      className={`${catBtnCls} ${
                        selectedCategory === cat.slug ? "tw-text-[#854ec9] tw-font-semibold" : "tw-text-[#14101c]"
                      }`}
                      onClick={() => onCategoryClick(cat.slug)}
                    >
                      <span>{cat.name}</span>
                      <span>({cat.post_count || 0})</span>
                    </button>
                  </li>
                ))}
              </ul>
            </div>
          </div>
        </div>
      </div>
    </main>
  );
}
