import Link from "next/link";
import formatDate from "@/helpers/FormatDate";
import React from "react";

const PostItem = ({ post, mainList = true }: { post: any; mainList?: boolean }) => {
  return (
    <article className="tw-group tw-flex tw-flex-col tw-h-full tw-rounded-2xl tw-border tw-border-solid tw-border-[#ece9f1] tw-bg-white tw-overflow-hidden tw-transition-all tw-duration-300 hover:tw-shadow-[0_14px_34px_rgba(20,16,28,0.12)] hover:tw--translate-y-1">
      <Link
        href={`/blog/${post.slug}`}
        target="_blank"
        rel="noopener noreferrer"
        className="tw-flex tw-flex-col tw-h-full tw-no-underline"
      >
        <div className="tw-relative tw-overflow-hidden tw-rounded-t-2xl tw-transform-gpu">
          <div className="tw-aspect-[16/10] tw-w-full tw-bg-[#f3f1f7]">
            {/* eslint-disable-next-line @next/next/no-img-element */}
            <img
              src={post.main_image || "/images/img-placeholder.png"}
              alt={post.title}
              className="tw-w-full tw-h-full tw-object-cover tw-transition-transform tw-duration-500 group-hover:tw-scale-105"
            />
          </div>
          {post.category_name && (
            <span className="tw-absolute tw-top-3 tw-left-3 tw-rounded-full tw-bg-white/95 tw-backdrop-blur tw-text-[#854ec9] tw-text-[11px] tw-font-bold tw-uppercase tw-tracking-wide tw-px-2.5 tw-py-1 tw-shadow-sm">
              {post.category_name}
            </span>
          )}
        </div>

        <div className="tw-flex tw-flex-col tw-flex-grow tw-p-5">
          <h3 className="tw-text-[17px] tw-font-bold tw-leading-snug tw-text-[#14101c] tw-mb-2 tw-line-clamp-2 group-hover:tw-text-[#854ec9] tw-transition-colors">
            {post.title}
          </h3>
          {post.excerpt && (
            <p className="tw-text-[14px] tw-leading-relaxed tw-text-[#5d556c] tw-mb-4 tw-line-clamp-3">
              {post.excerpt}
            </p>
          )}

          <div className="tw-mt-auto tw-flex tw-items-center tw-flex-wrap tw-gap-x-2 tw-gap-y-1 tw-text-[12.5px] tw-text-[#8a8398] tw-pt-3 tw-border-0 tw-border-t tw-border-solid tw-border-[#f0eef4]">
            <span className="tw-font-semibold tw-text-[#14101c]">
              {post.author_name}
            </span>
            <span aria-hidden="true">·</span>
            <span>{formatDate(new Date(post.created_at))}</span>
          </div>
        </div>
      </Link>
    </article>
  );
};

export default PostItem;
